import {countries} from './countries.js';
const aliases={usa:'840',us:'840','united states':'840',america:'840',uk:'826','great britain':'826',britain:'826',uae:'784',sg:'702',malaysia:'458',czechia:'203','south korea':'410','north korea':'408','ivory coast':'384','cote divoire':'384','east timor':'626',turkiye:'792'};
export const normalizeCountry=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
export function searchCountries(query){const q=normalizeCountry(query);if(!q)return [];const alias=aliases[q];return countries.filter(c=>c.id===alias||normalizeCountry(c.name).includes(q)).sort((a,b)=>(b.id===alias)-(a.id===alias)||Number(normalizeCountry(b.name).startsWith(q))-Number(normalizeCountry(a.name).startsWith(q))||a.name.localeCompare(b.name)).slice(0,8);}
export function initCountrySearch({input,results,form,onSelect,message}){let matches=[],active=-1;function close(){results.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1}function select(country){input.value=country.name;close();message.textContent='';onSelect(country)}function render(){results.replaceChildren();matches.forEach((c,i)=>{const button=document.createElement('button');button.type='button';button.role='option';button.id='country-result-'+i;button.textContent=c.name;button.setAttribute('aria-selected',String(i===active));button.onclick=()=>select(c);results.append(button)});results.hidden=!matches.length;input.setAttribute('aria-expanded',String(matches.length>0));if(active>=0)input.setAttribute('aria-activedescendant','country-result-'+active);else input.removeAttribute('aria-activedescendant')}
input.addEventListener('input',()=>{matches=searchCountries(input.value);active=-1;message.textContent=input.value.trim()&&!matches.length?'No matching country.':'';render()});input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return}if((e.key==='ArrowDown'||e.key==='ArrowUp')&&matches.length){e.preventDefault();active=active<0?(e.key==='ArrowDown'?0:matches.length-1):(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;render()}});form.addEventListener('submit',e=>{e.preventDefault();matches=searchCountries(input.value);if(matches.length)select(matches[active>=0?active:0]);else{message.textContent='Enter a country name to search.';close()}});document.addEventListener('click',e=>{if(!form.contains(e.target))close()});return {clear(){matches=[];input.value='';message.textContent='';close()}};}
